   $('name').textContent=player.name||'Mi perfil';$('identity').textContent=[player.club,player.category,player.dorsal!=null?'Dorsal '+player.dorsal:''].filter(Boolean).join(' · ');fillProfile();photo(modules.get('foto_url'));$('coach-tools').hidden=accessRole!=='admin_coach';for(const input of document.querySelectorAll('[data-coach-field]')){input.value=modules.get('coach_eval_v1')?.[input.dataset.coachField]??'';}
