 async function cropPhoto(file){
  const image=await createImageBitmap(file);try{session.assert();}catch(e){image.close();throw e;}
  return new Promise((resolve,reject)=>{
   const dialog=node('dialog',null,$('private'));dialog.className='photo-crop';node('h2','Ajustar foto',dialog);node('p','Arrastrá para encuadrar y ajustá el acercamiento.',dialog);
   const canvas=node('canvas',null,dialog);canvas.width=canvas.height=640;canvas.setAttribute('aria-label','Vista previa del recorte');const ctx=canvas.getContext('2d');const label=node('label','Acercar',dialog),range=node('input',null,label);range.type='range';range.min='1';range.max='4';range.step='0.01';range.value='1';let x=0,y=0,zoom=1,drag,closed=false;
   const finish=value=>{if(closed)return;closed=true;observer.disconnect();image.close();dialog.close();dialog.remove();resolve(value);};
   const observer=new MutationObserver(()=>{if($('private').hidden)finish(null);});observer.observe($('private'),{attributes:true,attributeFilter:['hidden']});
   const draw=()=>{const scale=Math.max(640/image.width,640/image.height)*zoom,w=image.width*scale,h=image.height*scale;x=Math.max(-(w-640)/2,Math.min((w-640)/2,x));y=Math.max(-(h-640)/2,Math.min((h-640)/2,y));ctx.clearRect(0,0,640,640);ctx.drawImage(image,(640-w)/2+x,(640-h)/2+y,w,h);};
   range.addEventListener('input',()=>{zoom=Number(range.value);draw();});canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!drag)return;const ratio=640/canvas.getBoundingClientRect().width;x+=(e.clientX-drag.x)*ratio;y+=(e.clientY-drag.y)*ratio;drag={x:e.clientX,y:e.clientY};draw();});for(const type of ['pointerup','pointercancel'])canvas.addEventListener(type,()=>drag=null);
   for(const [text,action] of [['Centrar',()=>{x=y=0;zoom=1;range.value='1';draw();}],['Cancelar',()=>finish(null)],['Usar foto',()=>{try{session.assert();finish(canvas.toDataURL('image/jpeg',.82));}catch(e){finish(null);reject(e);}}]]){const b=node('button',text,dialog);b.type='button';b.addEventListener('click',action);}dialog.addEventListener('cancel',e=>{e.preventDefault();finish(null);});draw();dialog.showModal();
  });
 }

